using Azure.Messaging.ServiceBus;using EnterpriseDocumentIntelligence.BuildingBlocks.Infrastructure;using EnterpriseDocumentIntelligence.BuildingBlocks.Messaging;using System.Text.Json;
public sealed class ServiceBusClientFactory(IConfiguration c){readonly ServiceBusClient client=!string.IsNullOrWhiteSpace(c["ServiceBus:ConnectionString"])?new(c["ServiceBus:ConnectionString"]!):new(c["ServiceBus:FullyQualifiedNamespace"]!,new Azure.Identity.DefaultAzureCredential());public ServiceBusProcessor Create(string t,string s)=>client.CreateProcessor(t,s,new ServiceBusProcessorOptions{MaxConcurrentCalls=8,PrefetchCount=50,AutoCompleteMessages=false});}
public sealed class Worker(ServiceBusClientFactory factory,IMessagePublisher publisher,ILogger<Worker> log):BackgroundService{protected override async Task ExecuteAsync(CancellationToken ct){var p=factory.Create("processing-events","embedding-sub");p.ProcessMessageAsync+=Handle;p.ProcessErrorAsync+=Error;await p.StartProcessingAsync(ct);try{await Task.Delay(Timeout.Infinite,ct);}catch(OperationCanceledException){}finally{await p.StopProcessingAsync();await p.DisposeAsync();}}async Task Handle(ProcessMessageEventArgs a){try{var m=JsonSerializer.Deserialize<DocumentProcessed>(a.Message.Body.ToString(),new JsonSerializerOptions(JsonSerializerDefaults.Web))??throw new InvalidOperationException("Invalid event");log.LogInformation("EmbeddingService processing Document={DocumentId} Correlation={CorrelationId}",m.DocumentId,m.CorrelationId);var embedded=m.Chunks.Select(c=>new EmbeddedChunk(c.ChunkId,c.Number,c.Text,c.TokenCount,Enumerable.Range(0,8).Select(i=>(float)((Math.Abs(c.Text.GetHashCode())>>(i%24))&255)/255f).ToArray())).ToArray();await publisher.PublishAsync(Topics.EmbeddingEvents,new EmbeddingsCreated(Guid.NewGuid(),m.TenantId,m.DocumentId,m.VersionId,embedded,DateTimeOffset.UtcNow,m.CorrelationId),m.CorrelationId,a.CancellationToken);await a.CompleteMessageAsync(a.Message);}catch(Exception ex){log.LogError(ex,"EmbeddingService failed");if(a.Message.DeliveryCount>=5)await a.DeadLetterMessageAsync(a.Message,"max-delivery",ex.Message);else await a.AbandonMessageAsync(a.Message);}}Task Error(ProcessErrorEventArgs e){log.LogError(e.Exception,"Service Bus error Entity={Entity}",e.EntityPath);return Task.CompletedTask;}}